import { test, expect } from '@playwright/test';

test.describe('Async Data Fetching - Non-blocking Initial Page Render', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/dashboard');
  });

  test('should display initial page content without waiting for async data', async ({ page }) => {
    // Verify initial page content is visible
    const header = page.getByRole('heading', { name: /dashboard/i });
    await expect(header).toBeVisible();

    const userList = page.getByRole('list', { name: /users/i });
    await expect(userList).toBeVisible();

    const userCount = page.getByText(/10 users/i);
    await expect(userCount).toBeVisible();

    // Verify async data fetching has not blocked initial render
    const loadingIndicator = page.getByRole('status', { name: /loading/i });
    await expect(loadingIndicator).toBeVisible();

    // Verify async data is loaded after initial render
    const userItem = page.getByRole('listitem', { name: /user/i });
    await expect(userItem).toBeVisible();

    // Verify async data is displayed
    const userName = page.getByText(/John Doe/i);
    await expect(userName).toBeVisible();

    // Verify async data is fully loaded
    const userEmail = page.getByText(/john.doe@example.com/i);
    await expect(userEmail).toBeVisible();

    // Verify loading indicator is gone
    await expect(loadingIndicator).not.toBeVisible();
  });

  test('should handle error state when async data fetching fails', async ({ page }) => {
    // Mock async data fetch failure
    await page.route('**/api/users', (route) => {
      route.abort('failed');
    });

    // Verify error state is displayed
    const errorMessage = page.getByText(/failed to load users/i);
    await expect(errorMessage).toBeVisible();

    // Verify loading indicator is still visible
    const loadingIndicator = page.getByRole('status', { name: /loading/i });
    await expect(loadingIndicator).toBeVisible();

    // Verify user list is empty
    const userList = page.getByRole('list', { name: /users/i });
    await expect(userList).toBeEmpty();

    // Verify error message is visible
    const errorList = page.getByRole('list', { name: /error/i });
    await expect(errorList).toBeVisible();

    // Verify error message contains specific text
    await expect(errorList).toContainText(/failed to load users/i);

    // Verify user count is not displayed
    const userCount = page.getByText(/10 users/i);
    await expect(userCount).not.toBeVisible();

    // Verify user item is not displayed
    const userItem = page.getByRole('listitem', { name: /user/i });
    await expect(userItem).not.toBeVisible();

    // Verify user email is not displayed
    const userEmail = page.getByText(/john.doe@example.com/i);
    await expect(userEmail).not.toBeVisible();

    // Verify error message is still visible after retry
    await page.reload();
    await expect(errorMessage).toBeVisible();
  });
});
